var app=angular.module('filterApp',[]); app.filter('startsWith',function(){return function(input,prefix){return (input||[]).filter(function(x){return x.indexOf(prefix)===0;}).join(', ');};}); app.service('messageService',function(){this.get=function(){return 'Hello from custom service';};}); app.controller('FilterCtrl',function($scope,$location,$http,$timeout,messageService){$scope.today=new Date();$scope.name='Vinutna Thode';$scope.price=12345.678;$scope.items=['Apple','Banana','Apricot','Mango'];$scope.lower=angular.lowercase('ANGULAR API');$scope.upper=angular.uppercase('angular api');$scope.custom=messageService.get();$scope.useLocation=function(){$scope.serviceMessage='Path: '+$location.path();};$scope.delay=function(){$scope.serviceMessage='Waiting...';$timeout(function(){$scope.serviceMessage='Message after $timeout';},800);};$scope.load=function(){$http.get('sample.json').then(function(r){$scope.httpInfo={config:JSON.stringify(r.config),data:JSON.stringify(r.data),status:r.status};},function(){ $scope.httpInfo={config:'GET config',data:'GET failed when served without server',status:0};});};$scope.post=function(){};});
